EasyQuestProfile.Script:
public class InfinityDefense
{
    private static bool Complete()
    {
        return wManager.Wow.Helpers.Quest.IsObjectiveComplete(1, 12470) ||
            wManager.Wow.Helpers.Lua.LuaDoString<int>("for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,c,_,id=GetQuestLogTitle(i) if not h and id==12470 and c==1 then return 1 end end return 0") == 1;
    }

    private static bool Enemy(int entry)
    {
        return entry == 27896 || entry == 27897 || entry == 27898 || entry == 27900;
    }

    public static void Run()
    {
        if (!wManager.Wow.Helpers.Quest.HasQuest(12470) || Complete()) return;
        var settings = wManager.wManagerSetting.CurrentSetting;
        bool mount = settings.UseMount;
        bool assist = settings.CanAttackUnitsAlreadyInFight;
        bool elite = settings.AttackElite;
        bool loot = settings.LootMobs;
        var center = new robotManager.Helpful.Vector3(4097.928f, -420.704f, 123.8515f);
        var deadline = System.DateTime.Now.AddMinutes(12);
        var nextSummon = System.DateTime.MinValue;
        var lastLog = System.DateTime.MinValue;
        int summons = 0;
        System.Threading.Thread fight = null;
        try
        {
            settings.UseMount = false;
            settings.CanAttackUnitsAlreadyInFight = true;
            settings.AttackElite = true;
            settings.LootMobs = false;
            wManager.Wow.Helpers.Lua.LuaDoString("if IsMounted() then Dismount() end");
            robotManager.Helpful.Logging.WriteDebug("[Infinity] Starting hourglass defense; ignoring invalid-height targets.");
            while (robotManager.Products.Products.IsStarted &&
                wManager.Wow.Helpers.Quest.HasQuest(12470) && !Complete() &&
                System.DateTime.Now < deadline)
            {
                if (wManager.Wow.ObjectManager.ObjectManager.Me.IsDead)
                {
                    robotManager.Helpful.Logging.WriteDebug("[Infinity] Player died; stopping for recovery.");
                    break;
                }
                var me = wManager.Wow.ObjectManager.ObjectManager.Me.Position;
                if (me.DistanceTo(center) > 45f)
                {
                    wManager.Wow.Bot.Tasks.GoToTask.ToPosition(center);
                    System.Threading.Thread.Sleep(500);
                    continue;
                }
                wManager.Wow.ObjectManager.WoWUnit hourglass = null;
                foreach (var unit in wManager.Wow.ObjectManager.ObjectManager.GetObjectWoWUnit())
                {
                    if (unit.Entry == 27840 && !unit.IsDead && unit.Position.DistanceTo(center) < 40f)
                    {
                        hourglass = unit;
                        break;
                    }
                }
                if (hourglass == null)
                {
                    if (System.DateTime.Now >= nextSummon)
                    {
                        if (summons >= 3)
                        {
                            robotManager.Helpful.Logging.WriteDebug("[Infinity] Hourglass failed three times; stopping.");
                            break;
                        }
                        if (wManager.Wow.Helpers.Lua.LuaDoString<int>("return GetItemCount(37923)") < 1)
                        {
                            robotManager.Helpful.Logging.WriteDebug("[Infinity] Missing Hourglass of Eternity (37923).");
                            break;
                        }
                        if (me.DistanceTo(center) > 5f)
                        {
                            wManager.Wow.Bot.Tasks.GoToTask.ToPosition(center);
                            System.Threading.Thread.Sleep(500);
                            continue;
                        }
                        wManager.Wow.Helpers.MovementManager.StopMove();
                        wManager.Wow.Helpers.Lua.LuaDoString("if IsMounted() then Dismount() end UseItemByName(37923)");
                        summons++;
                        nextSummon = System.DateTime.Now.AddSeconds(25);
                        robotManager.Helpful.Logging.WriteDebug("[Infinity] Summoning hourglass, attempt " + summons);
                        System.Threading.Thread.Sleep(4000);
                    }
                    System.Threading.Thread.Sleep(500);
                    continue;
                }
                var anchor = hourglass.Position;
                wManager.Wow.ObjectManager.WoWUnit target = null;
                float nearest = float.MaxValue;
                foreach (var unit in wManager.Wow.ObjectManager.ObjectManager.GetObjectWoWUnit())
                {
                    if (!Enemy(unit.Entry) || unit.IsDead) continue;
                    var position = unit.Position;
                    if (System.Math.Abs(position.Z - anchor.Z) > 18f || position.DistanceTo2D(anchor) > 40f) continue;
                    if (unit.GetDistance < nearest)
                    {
                        nearest = unit.GetDistance;
                        target = unit;
                    }
                }
                if (target != null)
                {
                    ulong guid = target.Guid;
                    robotManager.Helpful.Logging.WriteDebug("[Infinity] Defending against " + target.Name + " distance=" + nearest);
                    fight = new System.Threading.Thread(() => wManager.Wow.Helpers.Fight.StartFight(guid, false, true));
                    fight.IsBackground = true;
                    fight.Start();
                    var fightEnd = System.DateTime.Now.AddSeconds(50);
                    while (fight.IsAlive && robotManager.Products.Products.IsStarted &&
                        System.DateTime.Now < fightEnd && System.DateTime.Now < deadline && !Complete())
                    {
                        wManager.Wow.ObjectManager.WoWUnit current = null;
                        foreach (var unit in wManager.Wow.ObjectManager.ObjectManager.GetObjectWoWUnit())
                            if (unit.Guid == guid) { current = unit; break; }
                        if (current == null || current.IsDead ||
                            System.Math.Abs(current.Position.Z - anchor.Z) > 18f ||
                            current.Position.DistanceTo2D(anchor) > 45f ||
                            wManager.Wow.ObjectManager.ObjectManager.Me.Position.DistanceTo2D(anchor) > 45f) break;
                        System.Threading.Thread.Sleep(300);
                    }
                    if (fight.IsAlive) wManager.Wow.Helpers.Fight.StopFight();
                    if (!fight.Join(5000))
                    {
                        robotManager.Helpful.Logging.WriteDebug("[Infinity] Combat did not stop; halting defense.");
                        break;
                    }
                    fight = null;
                }
                else
                {
                    if (me.DistanceTo2D(anchor) > 7f)
                        wManager.Wow.Bot.Tasks.GoToTask.ToPosition(anchor);
                    else
                        wManager.Wow.Helpers.MovementManager.StopMove();
                    if ((System.DateTime.Now - lastLog).TotalSeconds > 20)
                    {
                        lastLog = System.DateTime.Now;
                        robotManager.Helpful.Logging.WriteDebug("[Infinity] Hourglass alive; waiting for next wave.");
                    }
                    System.Threading.Thread.Sleep(500);
                }
            }
        }
        finally
        {
            if (fight != null && fight.IsAlive)
            {
                wManager.Wow.Helpers.Fight.StopFight();
                if (!fight.Join(5000))
                    robotManager.Helpful.Logging.WriteDebug("[Infinity] Combat thread still exiting.");
            }
            wManager.Wow.Helpers.MovementManager.StopMove();
            settings.UseMount = mount;
            settings.CanAttackUnitsAlreadyInFight = assist;
            settings.AttackElite = elite;
            settings.LootMobs = loot;
        }
        bool completed = Complete();
        robotManager.Helpful.Logging.WriteDebug("[Infinity] Finished; quest complete=" + completed);
        if (robotManager.Products.Products.IsStarted && !completed)
            robotManager.Products.Products.ProductStop();
    }
}
public class MyCustomScript
{
    static MyCustomScript()
    {
        // You can put here code to run when bot start, you can also add methods and classes.
    }
}
